def is_prime(n):
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True


def is_palindrome(n):
    nums = str(n)
    left, right = 0, len(nums) - 1
    while left < right:
        if nums[left] != nums[right]:
            return False
        left, right = left + 1, right - 1
    return True


def is_perfect(n):
    if n < 2:
        return False
    total = 0
    for d in range(1, n // 2 + 1):
        if n % d == 0:
            total += d
    return total == n


def segment_report(start, end):
    if start > end:
        raise ValueError('start must be <= end')
    classes = {'prime': 0, 'palindrome': 0, 'perfect': 0, 'even': 0, 'odd': 0}
    largest_prime = None
    for n in range(start, end + 1):
        if is_prime(n):
            classes['prime'] += 1
            largest_prime = n
        if is_palindrome(n):
            classes['palindrome'] += 1
        if is_perfect(n):
            classes['perfect'] += 1
        classes['even' if n % 2 == 0 else 'odd'] += 1
    return {'range': (start, end), 'counts': classes, 'largest_prime': largest_prime}


print(segment_report(1, 30))
print(is_perfect(28), is_palindrome(121))
