import logging, time
from dataclasses import dataclass

logging.basicConfig(level=logging.INFO, format='%(levelname)s %(message)s')

@dataclass
class RunConfig:
    max_attempts: int = 3
    base_delay: float = 0.01
    timeout_s: float = 1.0
    fail_fast: bool = False


def run_task(name, fn, cfg, sleep=time.sleep, clock=time.monotonic):
    attempts = 0
    delay = cfg.base_delay
    started = clock()
    last_error = None
    while attempts < cfg.max_attempts:
        attempts += 1
        try:
            value = fn()
            return {'task': name, 'status': 'ok', 'attempts': attempts, 'value': value, 'seconds': round(clock() - started, 3)}
        except Exception as e:  # isolation: ek task ka failure poore run ko na rokta
            last_error = f'{type(e).__name__}: {e}'
            logging.warning('task %s attempt %d failed (%s)', name, attempts, last_error)
            if attempts < cfg.max_attempts:
                sleep(delay)
                delay *= 2
    return {'task': name, 'status': 'failed', 'attempts': attempts, 'error': last_error, 'seconds': round(clock() - started, 3)}


def run_batch(tasks, cfg, sleep=time.sleep, clock=time.monotonic):
    results = []
    for name, fn in tasks:
        result = run_task(name, fn, cfg, sleep=sleep, clock=clock)
        results.append(result)
        if cfg.fail_fast and result['status'] == 'failed':
            break
    return results


def summary(results):
    ok = sum(1 for r in results if r['status'] == 'ok')
    retried = sum(1 for r in results if r['attempts'] > 1)
    return {'ran': len(results), 'ok': ok, 'failed': len(results) - ok, 'retried': retried,
            'total_seconds': round(sum(r['seconds'] for r in results), 3)}


state = {'calls': 0}

def flaky():
    state['calls'] += 1
    if state['calls'] < 3:
        raise ConnectionError('temporary network error')
    return 'payload'


def broken():
    raise ValueError('bad input')


cfg = RunConfig()
results = run_batch([('fetch', flaky), ('parse', broken), ('write', lambda: 'written')], cfg, sleep=lambda _s: None)
print([(r['task'], r['status'], r['attempts']) for r in results])
print(summary(results))
